// Validate YAML in corpus files: whole YAML files, front matter, ```yaml fences, and #| hashpipe blocks.
const fs = require('fs');
const path = require('path');
const YAML = require('yaml');

function check(label, src) {
  const docs = YAML.parseAllDocuments(src, { version: '1.2', uniqueKeys: true });
  const arr = Array.isArray(docs) ? docs : [docs];
  let ok = true;
  for (const d of arr) {
    for (const e of d.errors) { ok = false; console.log(`  ERROR ${label}: ${e.message.split('\n')[0]}`); }
    for (const w of d.warnings) { console.log(`  warn  ${label}: ${w.message.split('\n')[0]}`); }
  }
  return ok;
}

function hashpipeBlocks(lines, prefixRe) {
  const blocks = [];
  let cur = null;
  lines.forEach((l, i) => {
    const m = l.match(prefixRe);
    if (m) {
      if (!cur) { cur = { start: i + 1, body: [] }; blocks.push(cur); }
      cur.body.push(m[1]);
    } else cur = null;
  });
  return blocks;
}

for (const f of process.argv.slice(2)) {
  let src = fs.readFileSync(f, 'utf8');
  if (src.charCodeAt(0) === 0xfeff) src = src.slice(1);
  const ext = path.extname(f).toLowerCase();
  const name = path.basename(f);
  console.log(`== ${name}`);
  const lines = src.replace(/\r\n?/g, '\n').split('\n');
  if (ext === '.yml' || ext === '.yaml') {
    check(name, src);
  } else if (['.md', '.qmd', '.rmd'].includes(ext)) {
    if (lines[0] === '---') {
      const end = lines.findIndex((l, i) => i > 0 && (l === '---' || l === '...'));
      check(`${name} front matter`, lines.slice(1, end).join('\n'));
    }
    // fenced yaml blocks
    for (let i = 0; i < lines.length; i++) {
      const m = lines[i].match(/^(\s*)(`{3,}|~{3,})\s*\{?\.?(ya?ml)\b([^`]*)$/);
      if (m) {
        const fence = m[2], indent = m[1].length;
        const body = [];
        let j = i + 1;
        while (j < lines.length && !lines[j].trim().startsWith(fence)) { body.push(lines[j].slice(indent)); j++; }
        if (/fmt:\s*skip/.test(m[4])) console.log(`  (skipped yaml fence at line ${i + 1})`);
        else check(`${name} yaml fence @${i + 1}`, body.join('\n'));
        i = j;
      }
    }
    for (const b of hashpipeBlocks(lines, /^#\|\s?(.*)$/)) check(`${name} #| @${b.start}`, b.body.join('\n'));
  } else if (ext === '.py' || ext === '.r') {
    for (const b of hashpipeBlocks(lines, /^\s*#\|\s?(.*)$/)) check(`${name} #| @${b.start}`, b.body.join('\n'));
  }
}

